/**
 * SPORT PACK (thème « sport », sport + esport) — données pures, AUCUN import (partagé avec convex/cardsCatalog.ts).
 * GÉNÉRÉ par scripts/make-sport.py (ne pas éditer à la main) depuis Tri-etoiles-sport.xlsx (SPEC-THEME-SPORT v5.1, « Étoiles finales »).
 * 7708 cartes · 114 sous-thèmes (libellé imprimé en grand sur la carte), regroupés à l'affichage en 10.
 * Numéro = « N° » de l'Excel, sur 7 708. Ids « spt-… » figés dans scripts/data/sport-ids.json (ne JAMAIS les changer).
 */
export type SportRarity = 'common' | 'uncommon' | 'rare' | 'epic' | 'legendary' | 'mythic';

export interface SportSub {
  id: string;
  label: string;
  code: string;
  /** groupe d'affichage (football, esport, combat…) */
  group: string;
}

export interface SportEntry {
  /** identifiant de carte — ne JAMAIS le changer */
  id: string;
  sub: string;
  /** n° de la carte dans tout le thème (1 → 7 708) */
  num: number;
  name: string;
  rarity: SportRarity;
  /** fichier dans art/sport ('' = aucune illustration : design typographique) */
  file: string;
  /** 'c' photo pleine · 'i' logo / détouré · '' aucune */
  art: '' | 'c' | 'i';
  /** type affiché (« Athlète », « Club », « Joueur esport »…) */
  label: string;
}

